import type { FrameworkApiReference } from '../types'
import { langChainLearningMeta } from './learning-meta'

type LangChainApiDraft = Omit<FrameworkApiReference, 'slug' | 'technologySlug' | 'maturity' | 'exampleLanguage'> & {
  slug: string
  maturity?: FrameworkApiReference['maturity']
}

const defineApi = ({ slug, maturity = 'stable', ...api }: LangChainApiDraft): FrameworkApiReference => {
  const learningMeta = langChainLearningMeta[api.name as keyof typeof langChainLearningMeta]
  if (!learningMeta) throw new Error(`Missing structured LangChain learning metadata for ${api.name}`)
  return {
    ...api,
    ...learningMeta,
    slug: `langchain-${slug}`,
    technologySlug: 'langchain',
    maturity,
    exampleLanguage: 'ts',
  }
}

