/**
 * Denominator: 101 public TypeScript APIs that application developers directly call or type against in
 * langchain@1.5.3, @langchain/core@1.2.3 and @langchain/textsplitters@1.0.1, plus three representative
 * official loader integrations. Excludes provider-specific model/integration catalogs, @langchain/classic,
 * LangGraph checkpoint/store APIs, LangSmith/deployment APIs, internal helpers and provider-only middleware.
 */
export const LANGCHAIN_FRAMEWORK_API_EXPECTED_COUNT = 101

export const langChainFrameworkApis: FrameworkApiReference[] = [
  ...agentApis,
  ...middlewareApis,
  ...modelApis,
  ...messageApis,
  ...toolApis,
  ...runnableApis,
  ...promptAndParserApis,
  ...retrievalApis,
]

if (langChainFrameworkApis.length !== LANGCHAIN_FRAMEWORK_API_EXPECTED_COUNT) {
  throw new Error(`LangChain framework API catalog mismatch: expected ${LANGCHAIN_FRAMEWORK_API_EXPECTED_COUNT}, got ${langChainFrameworkApis.length}`)
}
